/**
 * node-pty 的纯 JS 替身（本项目 Android 专用）—— 用 child_process 管道顶替原生 PTY。
 *
 * 为什么需要它：DSH 内核 0.2.0-rc.2 的 `dsh-subprocess-local` 依赖原生模块 `node-pty`
 * 来做终端会话（`requireNodePty().spawn(...)`），而我们的 payload **不打包原生模块**
 * （node 是 Termux 构建、只带我们需要的库）。缺它就报：
 *   Terminal error: Cannot find module 'node-pty'
 * 又因为 node-pty 是带 libutil/native 的 addon，在 Android 上现成二进制很难拿到，
 * 所以这里按"项目一贯做法"（历史上 subprocess-local 也被改成 child_process）给一个
 * 纯 JS 实现，覆盖 DSH 实际用到的 API 面：
 *
 *   spawn(file, args, options) → {
 *     pid, process,
 *     onData(cb) → { dispose() },
 *     onExit(cb) → { dispose() },     // cb({ exitCode, signal })
 *     write(data), resize(cols, rows), kill(signal),
 *     pause(), resume(), clear()
 *   }
 *
 * ⚠ 限制（如实说明，别当成完整 PTY）：
 *   · **没有真 TTY**：isatty 为假、没有作业控制/前台进程组、CSI 行编辑与回显由子进程自己决定
 *     → 交互式 shell 的提示符/回显不如真 PTY 完整，依赖 tty 的 TUI（vim、top 等）不能正常工作；
 *   · resize() 是空操作（管道没有窗口尺寸）；
 *   · 退出信号统一报 0（管道拿不到 signal 细节）。
 *   普通命令执行、把输出喂给终端面板这两件事是可用的。
 */
'use strict';

const { spawn } = require('node:child_process');

function spawnPty(file, args, options) {
  const opts = options || {};
  let argv = Array.isArray(args) ? args.slice() : [];

  // 管道没有 TTY，shell 默认跑非交互模式 → 不打提示符，DSH 会一直停在「正在启动…」。
  // 而且我们的 "bash" 其实是 `payload/bin/bash`（wrapper → /system/bin/sh = mksh），
  // DSH 按 bash 语义传的 `--noprofile` / `--norc` / `--` 它都不认（实测报 `--: unknown option`）。
  // 所以对 shell 命令：**只留 -i**，丢掉其余参数，让它进交互模式打提示符。
  const base = String(file || '').split('/').pop() || '';
  if (/(^|-)sh$/.test(base) || base === 'bash') {
    argv = ['-i'];
  }

  const child = spawn(file, argv, {
    cwd: opts.cwd || process.cwd(),
    env: opts.env || process.env,
    stdio: ['pipe', 'pipe', 'pipe'],
    windowsHide: true,
    detached: false
  });

  const dataCbs = [];
  const exitCbs = [];
  let exited = false;

  const emitData = (buf) => {
    if (!buf || !buf.length) return;
    const text = buf.toString('utf8');
    for (const cb of dataCbs.slice()) {
      try { cb(text); } catch (e) { /* 单个回调异常不影响其它 */ }
    }
  };

  child.stdout.on('data', emitData);
  child.stderr.on('data', emitData);
  child.on('error', (err) => {
    emitData(Buffer.from('\r\n' + String((err && err.message) || err) + '\r\n', 'utf8'));
  });
  child.on('exit', (code, signal) => {
    exited = true;
    const payload = { exitCode: typeof code === 'number' ? code : (signal ? 143 : 0), signal: 0 };
    for (const cb of exitCbs.slice()) {
      try { cb(payload); } catch (e) { /* 忽略 */ }
    }
  });

  return {
    pid: child.pid,
    process: child,
    onData(cb) {
      dataCbs.push(cb);
      return { dispose() { const i = dataCbs.indexOf(cb); if (i >= 0) dataCbs.splice(i, 1); } };
    },
    onExit(cb) {
      exitCbs.push(cb);
      return { dispose() { const i = exitCbs.indexOf(cb); if (i >= 0) exitCbs.splice(i, 1); } };
    },
    write(data) {
      if (exited) return;
      try { child.stdin.write(typeof data === 'string' ? data : String(data)); } catch (e) { /* 管道已关 */ }
    },
    resize() { /* 管道无窗口尺寸，忽略 */ },
    kill(signal) {
      try { child.kill(signal || 'SIGTERM'); } catch (e) { /* 已退出 */ }
    },
    pause() {
      try { child.stdout.pause(); child.stderr.pause(); } catch (e) { /* 忽略 */ }
    },
    resume() {
      try { child.stdout.resume(); child.stderr.resume(); } catch (e) { /* 忽略 */ }
    },
    clear() { /* 无缓冲区，忽略 */ }
  };
}

module.exports = {
  spawn: spawnPty,
  // 少数调用点会用 open() 别名（node-pty 里 fork/open 都是 spawn 的包装）
  open: spawnPty
};
